xgboost.pseudocode:
def split_gain(GL, HL, GR, HR, lam, gamma):
    # 2차 근사 목적함수 감소량 − 잎 추가 벌점 γ
    def score(G, H):
        return G * G / (H + lam)
    return 0.5 * (score(GL, HL) + score(GR, HR)
                  - score(GL + GR, HL + HR)) - gamma

def best_split(samples, lam=1.0, gamma=0.0):
    # samples: (특성값, g, h) → 정렬 후 왼쪽 누적합으로 탐색
    samples = sorted(samples)
    G = sum(s[1] for s in samples)
    H = sum(s[2] for s in samples)
    GL = HL = 0.0
    best = (0.0, None)
    for i in range(len(samples) - 1):
        GL += samples[i][1]
        HL += samples[i][2]
        if samples[i][0] == samples[i + 1][0]:
            continue  # 같은 값 사이는 분할 불가
        gain = split_gain(GL, HL, G - GL, H - HL,
                          lam, gamma)
        if gain > best[0]:
            thr = (samples[i][0] + samples[i + 1][0]) / 2
            best = (gain, thr)
    return best  # 이득 ≤ 0 이면 분할하지 않음
